#!/usr/bin/env node
/**
 * Keeps docs/feature-status.md honest.
 *
 *   node scripts/check-feature-status.mjs          # check (CI)
 *   node scripts/check-feature-status.mjs --write  # regenerate docs/feature-status.md
 *
 * Source of truth: frontend/lib/capabilities.ts. Features whose mode is "mock" must
 * never be listed as Available; the generated file is compared byte-for-byte so
 * hand edits that advertise a mock feature as available fail the check.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const capabilitiesPath = join(root, "frontend/lib/capabilities.ts");
const statusPath = join(root, "docs/feature-status.md");

const LABELS = {
  chat: "Agent chat",
  tasks: "Tasks",
  activity: "Activity and audit",
  telegram: "Telegram channel",
  google: "Google Workspace (Gmail, Calendar, Drive)",
  memory: "Memory",
  automations: "Automations and scheduler",
};

const PLANNED = [
  "Calendar module",
  "Knowledge",
  "Growth",
  "Local worker",
];

export function parseCapabilities(source) {
  const match = source.match(
    /export const capabilities[^=]*=\s*\{([\s\S]*?)\n\}\s*;/,
  );
  if (!match) throw new Error("Could not find `capabilities` object literal.");
  const result = {};
  for (const m of match[1].matchAll(/(\w+)\s*:\s*"(api|mock)"/g)) {
    result[m[1]] = m[2];
  }
  if (Object.keys(result).length === 0) {
    throw new Error("No capability entries parsed from capabilities.ts.");
  }
  return result;
}

export function render(caps) {
  const rows = Object.entries(caps).map(([key, mode]) => {
    const label = LABELS[key] ?? key;
    const status = mode === "api" ? "Available" : "Mock / not available";
    return `| ${label} | \`${key}\` | \`${mode}\` | ${status} |`;
  });
  return [
    "# Feature status",
    "",
    "<!-- Generated by scripts/check-feature-status.mjs from frontend/lib/capabilities.ts. Do not edit by hand. -->",
    "",
    "Run `node scripts/check-feature-status.mjs --write` after changing capabilities.",
    "CI fails if a `mock` capability is advertised as Available.",
    "",
    "| Feature | Capability key | Mode | Status |",
    "| --- | --- | --- | --- |",
    ...rows,
    "",
    "`api` means the UI is backed by the live backend. `mock` means simulated data and",
    "must not be presented as a working feature.",
    "",
    "## Planned (not implemented)",
    "",
    ...PLANNED.map((p) => `- ${p}`),
    "",
  ].join("\n");
}

function main() {
  const caps = parseCapabilities(readFileSync(capabilitiesPath, "utf8"));
  const expected = render(caps);

  if (process.argv.includes("--write")) {
    writeFileSync(statusPath, expected);
    console.log(`Wrote ${statusPath}`);
    return;
  }

  if (!existsSync(statusPath)) {
    console.error(
      "docs/feature-status.md is missing. Run: node scripts/check-feature-status.mjs --write",
    );
    process.exit(1);
  }
  const actual = readFileSync(statusPath, "utf8");
  const errors = [];

  for (const [key, mode] of Object.entries(caps)) {
    if (mode !== "mock") continue;
    const row = actual
      .split("\n")
      .find((line) => line.includes(`\`${key}\``) && line.startsWith("|"));
    if (row && /\bAvailable\b/.test(row)) {
      errors.push(`Mock feature \`${key}\` is advertised as Available: ${row}`);
    }
  }
  if (actual !== expected) {
    errors.push(
      "docs/feature-status.md is out of date with frontend/lib/capabilities.ts. Run: node scripts/check-feature-status.mjs --write",
    );
  }

  if (errors.length > 0) {
    for (const e of errors) console.error(`feature-status: ${e}`);
    process.exit(1);
  }
  console.log("feature-status: OK");
}

main();
